import{_ as e,o as t,c as d,a2 as o}from"./chunks/framework.BM5YPQmL.js";const h=JSON.parse('{"title":"应用侧的 OTA / A-B 服务","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/ota.md","filePath":"zh/l1/ota.md"}'),s={name:"zh/l1/ota.md"};function n(c,a,p,l,r,i){return t(),d("div",null,[...a[0]||(a[0]=[o(`<h1 id="应用侧的-ota-a-b-服务" tabindex="-1">应用侧的 OTA / A-B 服务 <a class="header-anchor" href="#应用侧的-ota-a-b-服务" aria-label="Permalink to &quot;应用侧的 OTA / A-B 服务&quot;">​</a></h1><p>更新机制住在 selfhost 服务（<code>ocos/services/selfhost/</code>）里； 应用通过 L1SVC &quot;ota&quot; 类别和配置存储触达它。</p><h2 id="l1svc-表面" tabindex="-1">L1SVC 表面 <a class="header-anchor" href="#l1svc-表面" aria-label="Permalink to &quot;L1SVC 表面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Op</th><th>命令</th><th>作用</th></tr></thead><tbody><tr><td>1</td><td><code>checkupdate</code></td><td>拉取并解析清单、比较（数值化构建号比较，BUG-0347）</td></tr><tr><td>2</td><td><code>config</code></td><td>list / get / set / restore / path - /etc/opencube.conf 存储</td></tr><tr><td>5</td><td><code>update</code></td><td><code>status</code> / <code>--local &lt;pkg&gt;</code> / 裸调用 = 在线链</td></tr><tr><td>6</td><td><code>rollback</code></td><td>把启动标志翻到另一个槽</td></tr><tr><td>7-16</td><td><code>update_pkg_test</code> .. <code>real_update_test</code></td><td>客户机内测试批次</td></tr></tbody></table><p><code>update status</code> 打印向导探测的机器画像：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>update: current version: 3.0.0-...</span></span>
<span class="line"><span>update: current boot: ISO          (or slot A / slot B)</span></span>
<span class="line"><span>update: next boot: (default)</span></span>
<span class="line"><span>update: available: none (up to date)</span></span>
<span class="line"><span>update: online update: enabled</span></span>
<span class="line"><span>update: A/B disk: present          &lt;- the wizard anchor</span></span></code></pre></div><h2 id="链条-在线流程做什么" tabindex="-1">链条（在线流程做什么） <a class="header-anchor" href="#链条-在线流程做什么" aria-label="Permalink to &quot;链条（在线流程做什么）&quot;">​</a></h2><p>check（从配置的 <code>update_url</code> 取清单）-&gt; download -&gt; verify （清单 SHA256 在 install 内强制执行）-&gt; 安装到<em>非活动</em>槽 -&gt; 设置启动标志 -&gt; &quot;reboot required&quot;。</p><p>离线：<code>update --local /path/to/package.tar.gz</code> 从挂载卷运行同 一条安装路径。</p><h2 id="a-b-盘" tabindex="-1">A/B 盘 <a class="header-anchor" href="#a-b-盘" aria-label="Permalink to &quot;A/B 盘&quot;">​</a></h2><p>两个槽 + 启动标志，由 <code>abdisk &lt;dev&gt;</code>（或 <code>disk-tool</code> 的 A/B 管理器向导）创建。GRUB 读标志；菜单提供强制选槽项。<code>abcfg</code> 显示这些命令写出的确切 grub.cfg。安装目标是非活动槽 （BUG-0110：由 <code>update_target_slot()</code> 决定，不由调用者决定）。</p><h2 id="配置键-etc-opencube-conf" tabindex="-1">配置键（/etc/opencube.conf） <a class="header-anchor" href="#配置键-etc-opencube-conf" aria-label="Permalink to &quot;配置键（/etc/opencube.conf）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>update_url=https://cubestudio-dev.github.io/OpenCubeOS/update.json</span></span>
<span class="line"><span>package_url=https://github.com/cubestudio-dev/OpenCubeOS/releases/latest</span></span>
<span class="line"><span>auto_check=no</span></span>
<span class="line"><span>online_update=yes</span></span>
<span class="line"><span>shell.lang=en</span></span></code></pre></div><p><code>config get update_url</code> 就是更新向导 DNS 步骤在解析之前拆解的 东西（scheme -&gt; host）。</p><h2 id="大应用" tabindex="-1">大应用 <a class="header-anchor" href="#大应用" aria-label="Permalink to &quot;大应用&quot;">​</a></h2><p><code>update</code>（无参数）= 5 步向导；其余一切参数形态都是逐字操作。 操作员视图见用户手册的 <a href="./../manual/update-ota.html">../manual/update-ota.md</a>，锚点纪律见 <a href="./wizard-library.html">wizard-library.md</a>。</p><h2 id="客户机内测试" tabindex="-1">客户机内测试 <a class="header-anchor" href="#客户机内测试" aria-label="Permalink to &quot;客户机内测试&quot;">​</a></h2><p><code>ab_partition_test</code>、<code>update_*_test</code> 批次、<code>checkupdate_test</code>、 <code>config_test</code> - 全部是 sysdiag/update 表的经典操作，全部在 注册表里。</p>`,18)])])}const b=e(s,[["render",n]]);export{h as __pageData,b as default};
